theorem call_uniform [DecidableEq Symbol] [DecidableEq (EdgeKey Symbol Guard)]
    {clear : Guard → Bool} {top : Guard} {input output : Value Symbol Guard}
    {before after : State Symbol Guard} {memo saved : Memo Symbol Guard}
    (actual : Call clear top input before memo output after saved) :
    ∃ bound, ∀ fuel, bound ≤ fuel → call clear top fuel fuel input before memo = .done output after saved := by

def constructionSyntax (key : Nat × Nat) (body : Value Symbol Guard) : Syntax Symbol Guard :=
  .binder true (InternedStoredSubstitution.encode (InternedStoredSubstitution.leaves body)
    [.intersection key.1 key.2] body)

def Heap (state : State Symbol Guard) : Prop :=
  ∀ key entry body depth ordinary, state.nodeRecords key = some (.mu entry body depth ordinary) →
    Correct entry body depth ordinary

def columns (rows : List (List Node)) : Nat → List (List Node)
  | 0 => []
  | arity + 1 => rows.filterMap List.head? :: columns (rows.map List.tail) arity

def makeEdge (symbol : Symbol) (constraint : Guard) (children : List (Value Symbol Guard)) :
    Work Symbol Guard (EdgeValue Symbol Guard) :=
  .edge ⟨symbol, children.map Value.referenceOf, constraint⟩ (fun entry => .mk entry children) Work.pure

def makeNode (edges : List (EdgeValue Symbol Guard)) : Work Symbol Guard (Value Symbol Guard) :=
  let kept := canonicalEdges (surviving edges)
  match kept with
  | [] => .pure .empty
  | first :: rest => .node (.node ((first :: rest).map (fun edge => edge.entry.identity)))
      (identifyNode (first :: rest)) Work.pure
